 goalsPage(){const gs=S.goals.filter(x=>x.status!=='archived');return`<div class=row><h1>Goals</h1><button class="btn pri" data-a=new>${ic('plus')} New goal</button></div>${gs.length?`<div>${gs.map(x=>{const p=Goal.progress(x),s=View.gstat(x),left=Math.max(0,Dt.diff(x.end,Dt.today()));return`<details class=grow><summary><span style="overflow-wrap:anywhere"><b>${e(x.name)}</b><br><span class=sub>${left} days left · ${Dt.fmt(x.end)}</span></span><span class=row style="flex-wrap:nowrap">${badge(View.gstatus(x),x.status==='completed'?'ok':x.status==='paused'?'wn':'')}<b class=num style="font-size:22px">${p}%</b></span></summary>${bar(p,'',x.name)}<p class=sub>${Dt.fmt(x.start)} → ${Dt.fmt(x.end)} · ${s.done} missions done · ${s.ms.filter(m=>!m.end).length} active missions · ${s.xp.toLocaleString()} XP</p><div class=mf style="justify-content:flex-start;margin-bottom:var(--s3)"><button class="btn" data-a=gv data-g=${x.id}>View</button>${x.status==='active'?`<button class="btn ghost" data-a=gs data-g=${x.id} data-s=paused>Pause</button><button class="btn ghost" data-a=gs data-g=${x.id} data-s=completed>Complete</button>`:x.status!=='completed'?`<button class="btn ghost" data-a=gs data-g=${x.id} data-s=active>Resume</button>`:''}</div></details>`}).join('')}</div>`:View.empty()}`},
