 xpWhy(d,s){const xs=S.xp.filter(x=>x.date===d),sum=t=>xs.filter(x=>x.type===t).reduce((a,x)=>a+x.amount,0),rows=[['Missions','MISSION'],['Daily bonus','DAILY_BONUS'],['Achievements','ACHIEVEMENT'],['Goal milestones','MILESTONE'],['Goal completed','GOAL_COMPLETED']],p=rows.map(r=>[r[0],sum(r[1])]).filter(r=>r[1]).map(r=>r[0]+' +'+r[1]);return p.length?'<br>'+p.join(' · '):''},
