const ChartUX={show(id,i){const c=CHARTS[id],w=document.querySelector(`[data-chart="${id}"]`);if(!c||!w)return;const x=c.r[i],v=c.val(x),prev=c.r[Math.max(0,i-1)],delta=v-c.val(prev),unit=c.xp?' XP':'%',tip=w.querySelector('[data-tip]'),lines=w.querySelectorAll('[data-crosshair]'),svg=w.querySelector('svg'),sr=svg.getBoundingClientRect(),wr=w.getBoundingClientRect();if(!tip)return;tip.innerHTML=`<span class=cap>${Dt.fmt(x.d,{weekday:'short',month:'short',day:'numeric'})}</span><strong>${v.toLocaleString()}${unit}</strong><span class="tip-delta ${delta<0?'down':''}">${e(delta===0?'No change from the previous day.':delta>0?`Up ${Math.abs(delta)}${unit} versus the previous day.`:`Down ${Math.abs(delta)}${unit} versus the previous day.`)}</span><div class=tip-change><b>What changed?</b><br>${e(delta>0?'Momentum improved versus the previous day.':delta<0?'Momentum softened versus the previous day.':'Performance held steady versus the previous day.')}</div>`;tip.hidden=false;const px=(c.X(i)/c.W)*sr.width+(sr.left-wr.left),py=(c.Y(v)/c.H)*sr.height+(sr.top-wr.top);tip.style.left=px+'px';tip.style.top=Math.max(12,py)+'px';lines[0].hidden=false;lines[0].setAttribute('x1',c.X(i));lines[0].setAttribute('x2',c.X(i));lines[1].hidden=false;lines[1].setAttribute('x2',c.X(i));lines[1].setAttribute('y1',c.Y(v));lines[1].setAttribute('y2',c.Y(v))},hide(id){const w=document.querySelector(`[data-chart="${id}"]`);if(!w)return;const p=chartPick[id];if(p!=null){this.show(id,p);return}const tip=w.querySelector('[data-tip]');if(tip)tip.hidden=true;w.querySelectorAll('[data-crosshair]').forEach(x=>x.hidden=true)}};
